CREATE OR REPLACE FUNCTION public.create_profile_on_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, avatar_url) VALUES (new.id, left(coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', ''), 100), CASE WHEN coalesce(new.raw_user_meta_data->>'avatar_url', '') LIKE 'https://%' THEN left(new.raw_user_meta_data->>'avatar_url', 2000) ELSE '' END); RETURN new; END $$;
REVOKE ALL ON FUNCTION public.create_profile_on_signup() FROM PUBLIC, anon, authenticated;